class Solution {
public:
    bool hasPair(vector<int>& nums, int target) {
        unordered_set<long long> seen;
        for (int x : nums) {
            if (seen.count((long long)target - x)) return true;
            seen.insert(x);
        }
        return false;
    }
};

class Solution {
public:
    vector<string> reverseWords(vector<string>& words) {
        vector<string> out(words.rbegin(), words.rend());
        return out;
    }
};

class Solution {
public:
    int countVowels(string s) {
        int n = 0;
        for (char c : s) if (string("aeiou").find(c) != string::npos) n++;
        return n;
    }
};
